function decorateIcons(root){if(root.nodeType===1&&root.closest('svg,script,style,option,textarea'))return;let walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);if(root.nodeType===3)nodes.push(root);for(let node of nodes){if(!node.parentElement||node.parentElement.closest('svg,script,style,option,textarea'))continue;let text=node.nodeValue;if(!Object.keys(iconSymbols).some(s=>text.includes(s)))continue;let fragment=document.createDocumentFragment(),buffer='';for(let char of text){if(iconSymbols[char]){if(buffer){fragment.append(document.createTextNode(buffer));buffer=''}let template=document.createElement('template');template.innerHTML=UI_ICONS[iconSymbols[char]];fragment.append(template.content.cloneNode(true))}else if(char!=='️')buffer+=char}if(buffer)fragment.append(document.createTextNode(buffer));node.replaceWith(fragment)}}
